using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.IO.Pipes;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.Xml;using MP1SkinStudio;using MP1SkinStudio.Live;
class WorkflowProbe{
 static StudioForm form;static StudioLiveClient client;static XmlDocument received;static int frames,checks;
 static object F(string n){return typeof(StudioForm).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);}
 static object Call(string n,params object[] a){return typeof(StudioForm).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic,null,a.Select(v=>v.GetType()).ToArray(),null).Invoke(form,a);}
 static void Wait(Func<bool> c){var t=Stopwatch.StartNew();while(!c()&&t.ElapsedMilliseconds<15000){Application.DoEvents();Thread.Sleep(20);}if(!c())throw new Exception("Timeout: "+((Label)F("liveNotice")).Text);}
 static void Check(bool c,string n){if(!c)throw new Exception(n);Console.WriteLine("PASS "+n);checks++;}
 static XmlDocument Snapshot(){received=null;client.Send(LiveWire.Document("snapshot"));Wait(()=>received!=null);var r=received;Wait(()=>(bool)F("liveVerified"));return r;}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);form=new StudioForm(StudioForm.DemoRoot());form.Show();Application.DoEvents();Check(((Panel)F("liveHost")).Visible,"Live connection controls are visible on startup");Call("ConnectLive");Wait(()=>((Button)F("liveOpen")).Enabled&&!(bool)F("liveBuilding"));Check(!(bool)F("liveVerified"),"Demo/source mismatch prevents live edits");Call("OpenPageFromLive");Wait(()=>(bool)F("liveVerified"));client=(StudioLiveClient)F("liveClient");client.Response+=d=>{if(d.DocumentElement.GetAttribute("command")=="snapshot")received=d;if(d.DocumentElement.GetAttribute("command")=="frame"&&d.DocumentElement.GetAttribute("ok")=="true")frames++;};string busyReason=null;using(var second=new StudioLiveClient(LiveEndpoint.Discover().Single())){second.Disconnected+=r=>busyReason=r;second.Start();Wait(()=>busyReason!=null);Check(busyReason.Contains("another Studio"),"Occupied bridge gives actionable connection guidance");}Check((bool)F("liveVerified"),"Rejected second client preserves the active connection");var snap=Snapshot();var project=(SkinProject)F("project");Check(String.Equals(project.Root,snap.DocumentElement.GetAttribute("skin"),StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(project.Page)==Path.GetFileName(snap.DocumentElement.GetAttribute("page")),"Open MP page adopts actual skin/theme/page and verifies disk hashes");var same=project;Call("OpenPageFromLive");Wait(()=>(bool)F("liveVerified"));Check(Object.ReferenceEquals(F("project"),same),"Opening the same MP page retains the current editor session");var target=project.Controls.First(c=>!c.IsBound("posX")&&!project.IsPropertyLocked(c,"posX")&&!c.AutomaticLayout&&!String.IsNullOrEmpty(c.Get("posX")));Call("SelectControl",target);var fields=(Dictionary<string,TextBox>)F("fields");string original=fields["posX"].Text,disk=File.ReadAllText(target.Source.Path);int before=frames;fields["posX"].Text=(Int32.Parse(original)+7).ToString();Wait(()=>frames>before);Check(!project.Dirty,"Typing previews geometry without Apply or modifying the editor XML");Call("OpenPageFromLive");Check(!(bool)F("liveOpenRequested")&&fields["posX"].Text==(Int32.Parse(original)+7).ToString(),"Pending input blocks page replacement and retains the draft");Call("RevertPropertyInputs");Wait(()=>!(bool)Call("PendingProperties"));Check(File.ReadAllText(target.Source.Path)==disk,"Reverting input preserves original disk XML");var invalid=(XmlDocument)snap.CloneNode(true);invalid.DocumentElement.SetAttribute("page","missing-workflow-page.xml");bool rejected=false;try{Call("OpenLiveSnapshot",invalid);}catch(TargetInvocationException){rejected=true;}Check(rejected&&Object.ReferenceEquals(F("project"),same),"Unreadable MP page retains the current editor session");fields=(Dictionary<string,TextBox>)F("fields");fields["posX"].Text=(Int32.Parse(original)+7).ToString();Call("Apply");var other=(XmlDocument)snap.CloneNode(true);other.DocumentElement.SetAttribute("skin",StudioForm.DemoRoot());other.DocumentElement.SetAttribute("theme","");other.DocumentElement.SetAttribute("page","demo.xml");bool cancelled=false;using(var timer=new System.Windows.Forms.Timer{Interval=30}){timer.Tick+=(s,e)=>{var d=Application.OpenForms.OfType<UnsavedSessionDialog>().FirstOrDefault();if(d!=null){timer.Stop();cancelled=true;d.DialogResult=DialogResult.Cancel;d.Close();}};timer.Start();try{Call("OpenLiveSnapshot",other);}catch(TargetInvocationException){}timer.Stop();}Check(cancelled&&Object.ReferenceEquals(F("project"),same)&&project.Dirty,"Cancel preserves unsaved work when adopting another MP page");Call("UndoEditor",false);Call("DisconnectLive");Wait(()=>F("liveClient")==null);Check(!((Button)F("liveOpen")).Enabled,"Disconnect disables page adoption and restores runtime overrides");Console.WriteLine(checks+" workflow checks passed.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(form!=null)form.Dispose();}}
}
